func _draw() -> void:
	# No generic paper/card rectangle: each activity now grows out of the room
	# object over the career-world theatre-light focus.
	last_widget_ground_route = ""
	var center := size * 0.5
	if mode == "pipe":
		_draw_pipe()
		if demo_active:
			_draw_demo_finger()
		return
	if mode == "echo":
		_draw_echo(center)
		if demo_active:
			_draw_demo_finger()
		return
	if mode == "pourt":
		_draw_pour_scene(center)
		if demo_active:
			_draw_demo_finger()
		return
	if mode == "oven":
		_draw_oven(center)
		if demo_active:
			_draw_demo_finger()
		return
	if mode == "xray_scan":
		_draw_xray_scan()
		if demo_active:
			_draw_demo_finger()
		return
	if mode == "dance_sequence":
		_draw_dance_sequence()
		if demo_active:
			_draw_demo_finger()
		return
	if mode in ["candy_sort", "geology_sort"]:
		_draw_candy_sort()
		if demo_active:
			_draw_demo_finger()
		return
	if mode == "paint_reveal":
		_draw_paint_reveal()
		if demo_active:
			_draw_demo_finger()
		return
	if mode == "farm_lob":
		_draw_farm_lob()
		if demo_active:
			_draw_demo_finger()
		return
	if mode == "boxer_rhythm":
		_draw_boxer_rhythm()
		if demo_active:
			_draw_demo_finger()
		return
	if mode == "clue_board":
		_draw_clue_board()
		if demo_active:
			_draw_demo_finger()
		return
	if mode == "crown_chest":
		_draw_crown_chest()
		if demo_active:
			_draw_demo_finger()
		return
	if mode == "garden_plant":
		_draw_garden_plant()
		if demo_active:
			_draw_demo_finger()
		return
	if mode == "magic_cabinet":
		_draw_magic_cabinet()
		if demo_active:
			_draw_demo_finger()
		return
	if _draw_causal_context(center):
		if demo_active:
			_draw_demo_finger()
		return
	if not widget_template.is_empty():
		_draw_widget_family_ground(center)
		_draw_widget_layers(center)
		if demo_active:
			_draw_demo_finger()
		return
	if visual_context.begins_with("nursery"):
		_draw_nursery_context(center)
		if demo_active:
			_draw_demo_finger()
		return
	match mode:
		"tap":
			# free placement: the marks ARE the picture; no hotspot to chase.
			# The ghost-finger demo teaches "touch here makes a mark".
			for mark: Vector2 in tap_marks:
				draw_circle(mark, 13.0, Color(accent, 0.85))
				draw_circle(mark, 6.0, Color.WHITE)
			if held:
				draw_circle(pointer_pos, 26.0, Color(accent, 0.35))
		"hold":
			draw_circle(center, minf(size.x, size.y) * 0.25, Color(accent, 0.24))
			draw_arc(center, minf(size.x, size.y) * 0.25, 0.0, TAU, 48, accent, 10.0)
			draw_circle(center, 24.0 if held else 16.0, Color.WHITE)
		"swipe":
			var span := minf(size.x, size.y) * 0.42
			var tail := center - swipe_dir * span
			var head := center + swipe_dir * span
			var side := swipe_dir.orthogonal()
			draw_line(tail, head, accent, 16.0, true)
			draw_colored_polygon(PackedVector2Array([
				head + side * 34.0, head + swipe_dir * 58.0, head - side * 34.0,
			]), accent)
			draw_circle(tail, 22.0, Color.WHITE)
		"circle":
			var radius := minf(size.x, size.y) * 0.26
			draw_arc(center, radius, -2.7, 2.2, 48, accent, 16.0)
			var tip := center + Vector2.from_angle(2.2) * radius
			draw_colored_polygon(PackedVector2Array([
				tip, tip + Vector2(-10, -36), tip + Vector2(30, -14),
			]), accent)
		"choice":
			var show_answer := choice_flash > 0.0 or demo_active
			for index in range(choice_count):
				var point := Vector2(size.x * (float(index) + 0.5) / float(choice_count), center.y)
				var is_answer := index == target_choice and show_answer
				var colour := Color(1.0, 0.86, 0.32) if is_answer else Color(0.34, 0.42, 0.62)
				draw_circle(point, 54.0, Color(colour, 0.34))
				draw_arc(point, 54.0, 0.0, TAU, 36, colour, 9.0)
				if is_answer:
					draw_circle(point, 15.0, Color.WHITE)
		"timing":
			var bar := Rect2(size.x * 0.12, center.y - 23.0, size.x * 0.76, 46.0)
			draw_rect(bar, Color(0.2, 0.23, 0.38), true)
			var good := Rect2(
				lerpf(bar.position.x, bar.end.x, timing_zone.x), bar.position.y,
				bar.size.x * (timing_zone.y - timing_zone.x), bar.size.y
			)
			draw_rect(good, Color(0.46, 0.94, 0.62), true)
			var marker_x := lerpf(bar.position.x, bar.end.x, timing_position)
			draw_line(Vector2(marker_x, bar.position.y - 28.0), Vector2(marker_x, bar.end.y + 28.0), Color.WHITE, 12.0)
		"bop":
			for target: Dictionary in bop_targets:
				if not bool(target.get("popped", false)):
					_draw_imp(target)
	if demo_active:
		_draw_demo_finger()


## Overlay ink bounds, cached per texture: the reveal must sweep the PAINTED
## band, not the whole 608px canvas. Sweeping the canvas made the pour
## saturate at 43% of the hold and then sit frozen — the exact playtest
## complaint ("no animation, no feedback").
var _ink_cache: Dictionary = {}

func _demo_finger_pose() -> Dictionary:
	var center := size * 0.5
	var cycle := fmod(demo_t, 2.4)
	var pressing := cycle > 1.1
	var at := center
	match mode:
		"tap":
			if _uses_anchored_targets():
				var target_index := _target_next_unplaced()
				if target_index >= 0:
					var target := _target_anchor_point(target_index)
					at = center.lerp(target, clampf(cycle / 1.0, 0.0, 1.0))
					pressing = cycle >= 1.0
			elif _is_nursery_burp_context():
				var pat_target := _nursery_burp_hand_point(1.0)
				at = center.lerp(pat_target, clampf(cycle / 0.9, 0.0, 1.0))
				pressing = cycle >= 0.9
		"swipe":
			if _is_nursery_bedtime_context():
				var blanket_index := _nursery_bedtime_next_blanket()
				if blanket_index >= 0:
					var blanket_start := _nursery_bedtime_grab_point(blanket_index)
					var blanket_end := blanket_start \
						+ Vector2.DOWN * _nursery_bedtime_required_travel()
					var blanket_travel := clampf(cycle / 1.65, 0.0, 1.0)
					blanket_travel = blanket_travel * blanket_travel \
						* (3.0 - 2.0 * blanket_travel)
					at = blanket_start.lerp(blanket_end, blanket_travel)
					pressing = cycle <= 1.78
			elif _uses_authored_trace_context():
				var trace_travel := lerpf(trace_journey, 1.0, clampf(cycle / 1.85, 0.0, 1.0))
				at = _trace_demo_point(trace_travel)
				pressing = cycle <= 1.95
			elif _uses_long_push_context():
				var push_travel := clampf(cycle / 1.85, 0.0, 1.0)
				push_travel = push_travel * push_travel * (3.0 - 2.0 * push_travel)
				at = _long_push_start().lerp(_long_push_end(), push_travel)
				pressing = cycle <= 1.95
			else:
				var direction := swipe_dir.normalized()
				if direction.length_squared() < 0.01:
					direction = Vector2.RIGHT
				var span := minf(size.x, size.y) * 0.34
				var travel := clampf(cycle / 1.85, 0.0, 1.0)
				travel = travel * travel * (3.0 - 2.0 * travel)
				at = center + direction * lerpf(-span, span, travel)
				pressing = true
		"circle":
			center = _circle_pivot()
			var radius := minf(size.x, size.y) * 0.26
			at = center + Vector2.from_angle(-2.7 + cycle * 2.0) * radius
			pressing = true
		"choice":
			var lane := Vector2(size.x * (float(target_choice) + 0.5) / float(choice_count), center.y)
			at = center.lerp(lane, clampf(cycle / 1.1, 0.0, 1.0))
		"timing":
			var bar_x := lerpf(size.x * 0.12, size.x * 0.88, timing_position)
			at = Vector2(bar_x, center.y + 58.0)
			pressing = timing_position >= timing_zone.x and timing_position <= timing_zone.y
		"bop":
			for target: Dictionary in bop_targets:
				if not bool(target.get("popped", false)):
					var pos: Vector2 = target.get("pos", Vector2.ZERO)
					at = center.lerp(pos, clampf(cycle / 1.1, 0.0, 1.0))
					break
		"hold":
			if _is_nursery_feed_context():
				var feed_pose := _nursery_feed_bottle_pose(true)
				at = feed_pose.get("position", center) as Vector2
				pressing = true
			elif _is_magic_vanish_context():
				var wand_target := _magic_vanish_wand_hit_rect().get_center()
				at = center.lerp(wand_target, clampf(cycle / 0.8, 0.0, 1.0))
				pressing = cycle >= 0.8
			else:
				pressing = true
		"pourt":
			# Approach the actual pitcher, then stay pressed while it would tilt.
			# A small rock makes the sustained grab readable without moving the
			# real gameplay state or pretending the bowl itself is the control.
			var pitcher_center := _pour_pitcher_rect().get_center()
			var approach := clampf(cycle / 0.8, 0.0, 1.0)
			at = center.lerp(pitcher_center, approach)
			pressing = cycle >= 0.8
			if pressing:
				at += Vector2(sin((cycle - 0.8) * 5.0) * 10.0, 0.0)
		"oven":
			var meter := _oven_meter_rect()
			var handle := _oven_handle_rect()
			if oven_t < 0.45 and not oven_done:
				# Watch the rising thermometer without showing a false early tap.
				at = Vector2(meter.get_center().x,
					meter.end.y - meter.size.y * clampf(oven_t, 0.0, 1.0))
				pressing = false
			else:
				# Once golden, travel from the meter to the real mitt handle and tap.
				var approach := clampf(cycle / 1.0, 0.0, 1.0)
				at = meter.get_center().lerp(handle.get_center(), approach)
				pressing = cycle >= 1.0
		"xray_scan":
			var scan_target := _xray_target_center(xray_found_count)
			var scan_start := _xray_home_point()
			var scan_travel := clampf(cycle / 1.65, 0.0, 1.0)
			scan_travel = scan_travel * scan_travel * (3.0 - 2.0 * scan_travel)
			at = scan_start.lerp(scan_target, scan_travel)
			pressing = cycle <= 1.78
		"pipe":
			var target_cell := _pipe_demo_target_cell()
			if target_cell >= 0:
				var destination := _pipe_cell_rect(target_cell).get_center()
				var start := center
				var demonstrates_drag := false
				var target_tile := String(pipe_grid[target_cell])
				if PIPE_MOUTHS.has(target_tile) and not pipe_fixed[target_cell]:
					# A stuck wrong pipe is lifted back toward the visible tray.
					start = destination
					destination = _pipe_tray_rect(pipe_tray.size()).get_center()
					demonstrates_drag = true
				elif not pipe_tray.is_empty():
					var slot := _pipe_demo_tray_slot(target_cell)
					slot = clampi(slot, 0, pipe_tray.size() - 1)
					start = _pipe_tray_rect(slot).get_center()
					demonstrates_drag = true
				var travel := clampf(cycle / 1.75, 0.0, 1.0)
				travel = travel * travel * (3.0 - 2.0 * travel)
				at = start.lerp(destination, travel)
				pressing = demonstrates_drag and cycle <= 1.85
		"dance_sequence":
			var pad := int(DANCE_SEQUENCE[0])
			if dance_listening:
				pad = int(DANCE_SEQUENCE[clampi(
					dance_input_index, 0, DANCE_SEQUENCE.size() - 1)])
				var dance_target := _dance_pad_rect(pad).get_center()
				at = Vector2(center.x, size.y * 0.94).lerp(
					dance_target, clampf(cycle / 1.0, 0.0, 1.0))
				pressing = cycle >= 1.0
			else:
				if dance_show_index >= 0 and dance_show_index < DANCE_SEQUENCE.size():
					pad = int(DANCE_SEQUENCE[dance_show_index])
				at = Vector2(_dance_pad_rect(pad).get_center().x, size.y * 0.94)
				pressing = false
		"candy_sort", "geology_sort":
			var candy_target := _candy_bin_rect(candy_type).get_center()
			var candy_travel := clampf((cycle - 0.35) / 1.45, 0.0, 1.0)
			candy_travel = candy_travel * candy_travel * (3.0 - 2.0 * candy_travel)
			at = candy_position.lerp(candy_target, candy_travel)
			pressing = cycle >= 0.35 and cycle <= 1.90
		"paint_reveal":
			var canvas := _paint_canvas_rect()
			var stroke_points: Array[Vector2] = [
				canvas.position + canvas.size * Vector2(0.16, 0.25),
				canvas.position + canvas.size * Vector2(0.84, 0.25),
				canvas.position + canvas.size * Vector2(0.16, 0.55),
				canvas.position + canvas.size * Vector2(0.84, 0.78),
			]
			var stroke_progress := clampf(cycle / 2.15, 0.0, 0.999)
			var stroke_scaled := stroke_progress * float(stroke_points.size() - 1)
			var stroke_index := clampi(floori(stroke_scaled), 0, stroke_points.size() - 2)
			at = stroke_points[stroke_index].lerp(
				stroke_points[stroke_index + 1], stroke_scaled - float(stroke_index))
			pressing = cycle >= 0.25 and cycle <= 2.18
		"farm_lob":
			var pull_target := _farm_demo_pull_point()
			var pull_travel := clampf(cycle / 1.15, 0.0, 1.0)
			pull_travel = pull_travel * pull_travel * (3.0 - 2.0 * pull_travel)
			at = _farm_anchor_point().lerp(pull_target, pull_travel)
			pressing = cycle <= 1.25
		"boxer_rhythm":
			if boxer_duck_pending:
				var duck_start := Vector2(center.x, size.y * 0.22)
				var duck_end := Vector2(center.x, size.y * 0.82)
				var duck_travel := clampf(cycle / 1.55, 0.0, 1.0)
				duck_travel = duck_travel * duck_travel * (3.0 - 2.0 * duck_travel)
				at = duck_start.lerp(duck_end, duck_travel)
				pressing = cycle <= 1.68
			else:
				var mitt_target := _boxer_mitt_rect(boxer_expected).get_center()
				at = Vector2(center.x, size.y * 0.92).lerp(
					mitt_target, clampf(cycle / 0.95, 0.0, 1.0))
				pressing = cycle >= 0.95
		"clue_board":
			var clue_target := _clue_target_rect(clue_index).get_center()
			var clue_travel := clampf(cycle / 1.6, 0.0, 1.0)
			clue_travel = clue_travel * clue_travel * (3.0 - 2.0 * clue_travel)
			at = _clue_home_point().lerp(clue_target, clue_travel)
			pressing = cycle <= 1.72
		"crown_chest":
			at = center.lerp(_crown_handle_rect().get_center(),
				clampf(cycle / 1.0, 0.0, 1.0))
			pressing = cycle >= 1.0
		"garden_plant":
			var hole := _garden_hole_point(garden_planted)
			var seed_travel := clampf(cycle / 1.55, 0.0, 1.0)
			seed_travel = seed_travel * seed_travel * (3.0 - 2.0 * seed_travel)
			at = _garden_seed_home().lerp(hole, seed_travel)
			pressing = cycle <= 1.68
		"magic_cabinet":
			var handle := _cabinet_handle_rect().get_center()
			var pull := clampf(cycle / 1.65, 0.0, 1.0)
			pull = pull * pull * (3.0 - 2.0 * pull)
			at = handle + Vector2.DOWN * _cabinet_required_travel() * pull
			pressing = cycle <= 1.78
		"echo":
			var verse: Array = ECHO_VERSES[clampi(echo_verse, 0, ECHO_VERSES.size() - 1)]
			if echo_listening and not verse.is_empty():
				# Her turn: approach and tap the next actual singing star.
				var next_note := int(verse[clampi(echo_input_i, 0, verse.size() - 1)])
				var target := _echo_star_center(next_note)
				at = Vector2(center.x, size.y * 0.84).lerp(target,
					clampf(cycle / 1.0, 0.0, 1.0))
				pressing = cycle >= 1.0
			else:
				# During the song the hand waits below the lit star; no press ring
				# invites an eager tap before the call-and-response turn begins.
				var watch_x := center.x
				if echo_show_i >= 0 and echo_show_i < verse.size():
					watch_x = _echo_star_center(int(verse[echo_show_i])).x
				at = center.lerp(Vector2(watch_x, size.y * 0.84),
					clampf(cycle / 0.8, 0.0, 1.0))
				pressing = false
	return {"at": at, "pressing": pressing}

func _draw_demo_finger() -> void:
	var pose := _demo_finger_pose()
	var at: Vector2 = pose.get("at", size * 0.5)
	var pressing := bool(pose.get("pressing", false))
	if _is_candymaker_pour() and pour_demo_hand_texture != null:
		# A literal hand is clearer than the generic concentric-dot hint against the
		# detailed workbench, and avoids reintroducing unexplained rings behind it.
		var side := 58.0 if pressing else 54.0
		var fingertip_uv := Vector2(0.455, 0.91)
		var hand_rect := Rect2(at - fingertip_uv * side, Vector2.ONE * side)
		draw_texture_rect(pour_demo_hand_texture, hand_rect, false,
			Color(1.0, 1.0, 1.0, 0.96))
		return
	var halo := 30.0 if pressing else 20.0
	draw_circle(at, halo, Color(0.22, 0.14, 0.52, 0.18))
	draw_circle(at, 14.5, Color("#382485"))
	draw_circle(at, 12.0, Color(1.0, 0.98, 0.86, 0.98))
	if pressing:
		var ring := 18.0 + fmod(demo_t * 46.0, 26.0)
		draw_arc(at, ring, 0.0, TAU, 24, Color(1.0, 0.95, 0.6, 0.6), 4.0)

func set_fill(value: float) -> void:
	widget_fill = clampf(value, 0.0, 1.0)
	if _uses_long_push_context():
		long_push_journey = widget_fill
	if _uses_authored_trace_context():
		trace_journey = widget_fill
	queue_redraw()

func _draw_ballet_demo() -> void:
	var travel := clampf((demo_t - 0.18) / 1.05, 0.0, 1.0)
	travel = travel * travel * (3.0 - 2.0 * travel)
	var at := size * 0.5
	match mode:
		"ballet_pose":
			var frames := pose_option_frames()
			var rects := pose_option_rects()
			var correct := 0
			for index in range(frames.size()):
				if int(frames[index]) == pose_target_frame():
					correct = index
					break
			at = pose_target_rect().get_center().lerp(rects[correct].get_center(), travel)
		"ballet_ribbon":
			var end := minf(1.0, ribbon_progress + 0.30)
			at = ribbon_point(lerpf(ribbon_progress, end, travel))
		"ballet_twirl":
			var direction := twirl_direction if twirl_direction != 0 else 1
			var angle := _twirl_handle_angle + float(direction) * TAU * 0.30 * travel
			at = twirl_center() + Vector2.from_angle(angle) * twirl_radius()
	_draw_ghost_finger(at, travel >= 0.72)

func _draw() -> void:
	if lesson.is_empty():
		return
	draw_style_box(StorybookUI.panel_style(Color("#a57ab3"), Color("#f8ead5"), 32, 7), BOARD)
	draw_line(Vector2(375, 420), Vector2(1135, 420), Color("#d8c2d3"), 4, true)
	_draw_hint_button()
	match lesson_kind():
		"pattern":
			_draw_pattern()
		"match":
			_draw_shape(int(lesson.get("target", 0)), Vector2(755, 285), 68.0)
		"count", "add":
			_draw_counting()
	var choices: Array = lesson.get("choices", []) as Array
	for index in range(choices.size()):
		var card := choice_rect(index)
		var fill := Color("#fffaf0") if can_answer() else Color("#dfdcde")
		if solved and index == chosen:
			fill = Color("#b6eadc")
		elif help_visible and can_answer() and index == answer_index():
			fill = Color("#fff0a9")
		draw_style_box(StorybookUI.panel_style(INK, fill, 25, 5), card)
		if lesson_kind() in ["count", "add"]:
			var amount := int(choices[index])
			var pearl_radius := _group_radius(amount, card.size.x - 24.0, 40.0)
			_draw_group(amount, card.get_center() + Vector2(0, -15),
				pearl_radius, Color("#75d3df"))
		else:
			_draw_shape(int(choices[index]), card.get_center(), 49.0)
	if not solved:
		_draw_demo()
	else:
		var at := choice_rect(answer_index()).get_center()
		for index in range(6):
			var angle := float(index) * TAU / 6.0 + idle_demo_t * 0.3
			_draw_shape(3, at + Vector2.from_angle(angle) * 118.0, 10.0)

func _draw_demo() -> void:
	var at := Vector2.ZERO
	if lesson_kind() == "add" and not joined:
		at = JOIN_CENTER
	elif counted.has(false):
		at = counter_position(counted.find(false))
	elif help_visible:
		at = choice_rect(answer_index()).get_center()
	elif lesson_kind() == "pattern":
		return
	else:
		return
	var pulse := 1.0 + sin(idle_demo_t * 4) * 0.12
	draw_arc(at, 41.0 * pulse, 0, TAU, 32, Color("#f2d58e"), 6, true)
	draw_circle(at + Vector2(25, 34), 11, Color("#fff4d5"))

func _draw_demo() -> void:
	var cycle := fmod(demo_t, 2.4) / 2.4
	var hand := int(floor(fmod(demo_t, 4.8) / 2.4))
	var start := glove_rest_position(hand)
	var target := active_target_position()
	if mode == "boxing_guide":
		target = guide_target_position(hand)
	elif mode == "boxing_guard":
		hand = _guard_side
		start = glove_rest_position(hand)
		target = guard_target_position(hand)
	elif mode == "boxing_belt":
		target = active_target_position()
	var travel := clampf(cycle / 0.72, 0.0, 1.0)
	travel = travel * travel * (3.0 - 2.0 * travel)
	var at := start.lerp(target, travel)
	draw_line(start, target, Color(PEARL_GOLD, 0.34), 6.0, true)
	draw_circle(at, 31.0, Color(PEARL_GOLD, 0.24))
	draw_circle(at, 18.0, Color(1.0, 0.97, 0.82, 0.92))
	draw_arc(at, 31.0 + sin(_elapsed * 7.0) * 4.0,
		0.0, TAU, 28, Color(PEARL_GOLD, 0.82), 5.0, true)

func _demo_finger_pose() -> Dictionary:
	var cycle := fmod(demo_t, 2.4)
	match mode:
		"geology_river":
			var unresolved := 0
			for index in range(RIVER_PATH.size()):
				var cell := RIVER_PATH[index]
				if not river_wet[cell.y * RIVER_COLS + cell.x]:
					unresolved = index
					break
			var next := mini(RIVER_PATH.size() - 1, unresolved + 1)
			return {"at": river_path_point(unresolved).lerp(river_path_point(next),
				clampf(cycle / 1.7, 0.0, 1.0)), "pressing": cycle < 1.8}
		"geology_fossil":
			if fossil_stage == 0:
				var row := _cleared_count() / FOSSIL_GRID_COLS
				var y := FOSSIL_RECT.position.y + (float(row) + 0.5) \
					* FOSSIL_RECT.size.y / float(FOSSIL_GRID_ROWS)
				return {"at": Vector2(lerpf(FOSSIL_RECT.position.x + 30.0,
					FOSSIL_RECT.end.x - 30.0, clampf(cycle / 1.7, 0.0, 1.0)), y),
					"pressing": cycle < 1.8}
			var piece := maxi(0, fossil_snapped.find(false))
			return {"at": fossil_piece_home(piece).lerp(fossil_piece_target(piece),
				clampf(cycle / 1.7, 0.0, 1.0)), "pressing": cycle < 1.8}
		"geology_pan":
			return {"at": PAN_RECT.get_center()
				+ Vector2(sin(cycle * TAU / 1.2) * 150.0, 0.0), "pressing": true}
		"geology_geode":
			if _seam_count() < GEODE_SEAM_SPOTS.size():
				return {"at": geode_seam_spot(maxi(0, geode_seams.find(false))),
					"pressing": fmod(cycle, 0.8) > 0.38}
			return {"at": geode_half_center() + Vector2(
				clampf(cycle / 1.7, 0.0, 1.0) * GEODE_PULL_DISTANCE, 0.0),
				"pressing": cycle < 1.8}
	return {"at": WORK_RECT.get_center(), "pressing": false}

func _draw() -> void:
	if mode != "kart_race":
		super._draw()
		return
	if kart.is_empty():
		return
	last_contextual_draw_route = "kart_shared_driving:painted_circuit"
	var lap := mini(Driving.LAPS - 1, floori(float(kart["s"]) / LAP_DISTANCE))
	for strip: Dictionary in ZOOM_STRIPS:
		var at := road_point(float(strip["u"]) * LAP_DISTANCE, float(strip["lat"]))
		if _boost_art != null:
			draw_texture_rect(_boost_art, Rect2(at - Vector2(22, 10), Vector2(44, 20)), false)
		else:
			draw_line(at - Vector2(16, 0), at + Vector2(16, 0), Color("#ffe299"), 9.0, true)
	for index in range(PEARLS.size()):
		if _collected.has(lap * PEARLS.size() + index):
			continue
		var pearl: Dictionary = PEARLS[index]
		var at := road_point(float(pearl["u"]) * LAP_DISTANCE, float(pearl["lat"]))
		draw_circle(at, 10.0, Color("#65547f"))
		draw_circle(at, 7.0, Color("#fff0ce"))
		draw_circle(at + Vector2(-2, -2), 2.5, Color.WHITE)
	var player_at := road_point(float(kart["s"]), float(kart["lat"]))
	var rival_at := road_point(float(rival["s"]), float(rival["lat"]))
	if player_at.y >= rival_at.y:
		_draw_car(rival, _rival_art, false)
		_draw_car(kart, _driver_art, true)
	else:
		_draw_car(kart, _driver_art, true)
		_draw_car(rival, _rival_art, false)
	_draw_race_controls()

func _draw_race_controls() -> void:
	for lap in range(Driving.LAPS):
		# Keep both lap flags beyond the shared upper-left back button.
		var center := Vector2(190 + lap * 88, 68)
		var done := float(kart["s"]) >= float(lap + 1) * LAP_DISTANCE
		draw_circle(center, 35, Color("#52406f"))
		draw_circle(center, 29, Color("#ffe2a0") if done else Color("#e7ddef"))
		# The dials are lap state, so give each one a tiny finish flag
		# instead of leaving an unexplained empty center.
		draw_line(center + Vector2(-10, 12), center + Vector2(-10, -13),
			Color("#655078"), 4.0, true)
		var flag_color := Color("#ee91b7") if done else Color("#8ccfd1")
		draw_colored_polygon(PackedVector2Array([
			center + Vector2(-8, -12), center + Vector2(13, -7),
			center + Vector2(-8, 0),
		]), flag_color)
		var fraction := clampf(float(kart["s"]) / LAP_DISTANCE - float(lap), 0.0, 1.0)
		if fraction > 0.001:
			draw_arc(center, 32, -PI * 0.5, -PI * 0.5 + TAU * fraction, 48,
				Color("#71d7d0"), 7, true)
	draw_style_box(_steering_style, STEERING_RECT)
	var center := STEERING_RECT.get_center()
	draw_line(center - Vector2(290, 0), center + Vector2(290, 0), Color("#b3ded7"), 14, true)
	for sign_value: float in [-1.0, 1.0]:
		var at := center + Vector2(sign_value * 316, 0)
		draw_polyline(PackedVector2Array([at + Vector2(-sign_value * 18, -16),
			at, at + Vector2(-sign_value * 18, 16)]), Color("#6b4e81"), 6, true)
	var knob := center + Vector2(race_steer * 270, 0)
	if demo_active:
		knob.x += sin(race_clock * 2.0) * 125.0
	draw_circle(knob, 49, Color("#665180"))
	draw_circle(knob, 42, Color("#e9b88a"))
	draw_arc(knob, 29, 0, TAU, 36, Color("#fff0d0"), 7, true)
	draw_line(knob, knob + Vector2(0, 26), Color("#fff0d0"), 6, true)
	if demo_active:
		_draw_demo_finger()
	draw_circle(TURBO_CENTER, TURBO_RADIUS, Color("#554274"))
	draw_circle(TURBO_CENTER, TURBO_RADIUS - 7, Color("#a5dedd"))
	var meter := float(kart["meter"])
	if meter > 0.001:
		draw_arc(TURBO_CENTER, 52, -PI * 0.5, -PI * 0.5 + TAU * meter, 48,
			Color("#ffe298"), 9, true)
	draw_colored_polygon(PackedVector2Array([TURBO_CENTER + Vector2(4, -33),
		TURBO_CENTER + Vector2(-23, 3), TURBO_CENTER + Vector2(-2, 3),
		TURBO_CENTER + Vector2(-6, 31), TURBO_CENTER + Vector2(24, -8),
		TURBO_CENTER + Vector2(4, -8)]), Color("#fff2bd"))
	if race_countdown > 0.0:
		for index in range(3):
			var lit := race_countdown <= 1.5 - float(index) * 0.5
			draw_circle(Vector2(550 + index * 90, 515), 28,
				Color("#ffe5a8") if lit else Color("#9abcc8"))

func _demo_finger_pose() -> Dictionary:
	if mode != "kart_race":
		return super._demo_finger_pose()
	return {"at": STEERING_RECT.get_center() + Vector2(sin(race_clock * 2.0) * 125.0, 0),
